/*
 * strings.js — GENERATED by tools/build_i18n.js. DO NOT EDIT BY HAND.
 *
 * Runtime translation table backing the manual language switch in
 * Settings. The static UI binds to src/i18n/*.json via $t() and follows
 * the device language automatically; this module exists for the cases
 * where the user has chosen a language that differs from the system one.
 *
 * Usage:
 *   import { tr, setLang, resolveLang } from '../../common/js/strings.js';
 *   tr('settings.autoCenter')        -> the string in the active language
 *   setLang('zh' | 'en' | 'system')  -> apply an override
 */

export const LANG_ZH = 'zh';
export const LANG_EN = 'en';

/* Active language. Starts as the device language and is replaced once
 * storage has been read (or the user picks one in Settings). */
let _lang = LANG_EN;

/* The device language, resolved once at startup from
 * configuration.getLocale(). Used as the target of the 'system' mode. */
let _systemLang = LANG_EN;

/* The user-facing preference: 'system' | 'zh' | 'en'. Kept separate from
 * _lang so that a locale change reported by the system does NOT silently
 * override an explicit choice the user made in Settings. */
let _mode = 'system';

/*
 * Record the device language and, if the user is following the system,
 * switch to it. Called on every page show and on configuration change.
 * Never clobbers an explicit zh/en override.
 */
export function setSystemLang(l) {
  _systemLang = (l === LANG_ZH) ? LANG_ZH : LANG_EN;
  if (_mode === 'system') _lang = _systemLang;
}

export function systemLang() { return _systemLang; }

export function setLang(mode) {
  if (mode === 'zh' || mode === LANG_ZH) { _mode = LANG_ZH; _lang = LANG_ZH; return; }
  if (mode === 'en' || mode === LANG_EN) { _mode = LANG_EN; _lang = LANG_EN; return; }
  /* anything else = follow the system */
  _mode = 'system';
  _lang = _systemLang;
}

export function getLang() { return _lang; }

export function getMode() { return _mode; }

/*
 * Resolve the language that should actually be used, given the stored
 * preference and the device locale. 'system' is the default.
 */
export function resolveLang(pref, deviceLang) {
  const dev = (deviceLang === LANG_ZH) ? LANG_ZH : LANG_EN;
  if (pref === LANG_ZH || pref === LANG_EN) return pref;
  return dev;
}

