/*
 * tr(key) — look up a string in the active language. Falls back to the
 * English entry, then to the key itself, so a missing key is visible
 * rather than blank.
 */
export function tr(key) {
  const row = TABLE[_lang] || TABLE.en;
  if (row && Object.prototype.hasOwnProperty.call(row, key)) return row[key];
  if (TABLE.en && Object.prototype.hasOwnProperty.call(TABLE.en, key)) return TABLE.en[key];
  return key;
}

export default { tr, setLang, setSystemLang, systemLang, getLang, getMode, resolveLang, LANG_ZH, LANG_EN };
